#!/usr/bin/env python3
"""Rebuilds the A2L fixtures from engine-v1.a2l (hand-written, modeled on real ECU A2Ls).

- engine-v1-reformatted.a2l: the same objects in reverse order, re-indented, with
  other comments and numbers written differently (as another generator would).
- engine-v2.a2l: v1 after a software rebuild: the calibration data and RAM
  variables moved, and one limit changed.
"""
import pathlib
import re

here = pathlib.Path(__file__).parent
v1 = (here / "engine-v1.a2l").read_text()

head, rest = v1.split("    /* ---------- Calibration ---------- */\n", 1)
body, tail = rest.split("\n  /end MODULE", 1)
objects = re.findall(r"    /begin (\w+).*?\n    /end \1\n", body, re.S)
blocks = [m.group(0) for m in re.finditer(r"    /begin (\w+).*?\n    /end \1\n", body, re.S)]
assert len(blocks) == len(objects) == 20, len(blocks)
reformatted = []
for b in reversed(blocks):
    b = re.sub(r"\n\s+", "\n\t", b.strip()) + "\n"
    b = b.replace("COEFFS_LINEAR 0.25 0", "COEFFS_LINEAR 0.250 0.0").replace("0x80010", "0X80010")
    reformatted.append("// generated by OtherTool 3.2\n" + b)
(here / "engine-v1-reformatted.a2l").write_text(head + "\n".join(reformatted) + "\n  /end MODULE" + tail)

v2 = v1.replace("0x800101", "0x800105").replace("0x800102", "0x800106").replace("0x800100", "0x800104")
v2 = v2.replace("0xD0001000", "0xD0002000")
v2 = v2.replace("UWORD CM_Speed 0 0 0 7000", "UWORD CM_Speed 0 0 0 8000")
(here / "engine-v2.a2l").write_text(v2)
